const DOM ={header: null,navLinks: null,sections: null,init(){this.header = document.querySelector('.header');this.navLinks = document.querySelectorAll('.nav-menu a');this.sections = document.querySelectorAll('section[id]');}};document.querySelectorAll('a[href^="#"]').forEach(anchor =>{anchor.addEventListener('click',function(e){e.preventDefault();const targetId = this.getAttribute('href').slice(1);const target = document.getElementById(targetId);if(target){const headerOffset = 80;let offsetPosition;const cachedSection = sectionDataCache.find(s => s.id === targetId);if(cachedSection && sectionCacheValid){offsetPosition = cachedSection.top - headerOffset;}else{const elementPosition = target.getBoundingClientRect().top;const pageYOffset = window.pageYOffset;offsetPosition = elementPosition + pageYOffset - headerOffset;}window.scrollTo({top: offsetPosition,behavior: 'smooth'});}});});let scrollTicking = false;const handleScroll =()=>{const currentScrollY = window.scrollY;if(DOM.header){if(currentScrollY > 50){DOM.header.classList.add('scrolled');}else{DOM.header.classList.remove('scrolled');}}updateActiveNav(currentScrollY);scrollTicking = false;};window.addEventListener('scroll',()=>{if(!scrollTicking){requestAnimationFrame(handleScroll);scrollTicking = true;}},{passive: true});const navObserverOptions ={threshold: 0.5,rootMargin: '-80px 0px -50% 0px'};const navObserver = new IntersectionObserver((entries)=>{if(!DOM.navLinks)DOM.navLinks = document.querySelectorAll('.nav-menu a');entries.forEach(entry =>{if(entry.isIntersecting){DOM.navLinks.forEach(link =>{link.classList.remove('active');if(link.getAttribute('href').slice(1)=== entry.target.id){link.classList.add('active');}});}});},navObserverOptions);DOM.sections = document.querySelectorAll('section[id]');DOM.sections.forEach(section => navObserver.observe(section));let sectionDataCache = [];let sectionCacheValid = false;function rebuildSectionCache(){if(!DOM.sections)DOM.sections = document.querySelectorAll('section[id]');sectionDataCache = Array.from(DOM.sections).map(section =>({id: section.id,top: section.offsetTop,height: section.offsetHeight}));sectionCacheValid = true;}function updateActiveNav(scrollY){if(!sectionCacheValid){rebuildSectionCache();}if(!DOM.navLinks)DOM.navLinks = document.querySelectorAll('.nav-menu a');let currentSectionId = null;const scrollPosition =(typeof scrollY === 'number' ? scrollY : window.scrollY)+ 100;for(const section of sectionDataCache){if(scrollPosition >= section.top && scrollPosition < section.top + section.height){currentSectionId = section.id;break;}}DOM.navLinks.forEach(link =>{const href = link.getAttribute('href').slice(1);if(currentSectionId && href === currentSectionId){link.classList.add('active');}else{link.classList.remove('active');}});}const observerOptions ={threshold: 0.1,rootMargin: '0px 0px -100px 0px'};const observer = new IntersectionObserver((entries)=>{requestAnimationFrame(()=>{entries.forEach(entry =>{if(entry.isIntersecting){entry.target.classList.add('active');observer.unobserve(entry.target);}});});},observerOptions);document.addEventListener('DOMContentLoaded',()=>{DOM.init();requestAnimationFrame(()=>{rebuildSectionCache();});requestAnimationFrame(()=>{const revealElements = document.querySelectorAll('.hero-content');revealElements.forEach(el =>{el.classList.add('reveal');observer.observe(el);});setTimeout(()=>{const otherElements = document.querySelectorAll('.book-card,.section-title,.about-content');otherElements.forEach(el =>{el.classList.add('reveal');observer.observe(el);});},500);});createMobileMenu();const idleInit =()=>{initParallax();initAudio();initParticles();initFAQ();};if('requestIdleCallback' in window){requestIdleCallback(idleInit,{timeout: 3000});}else{setTimeout(idleInit,1000);}updateActiveNav();let rebuildTimeout;const resizeObserver = new ResizeObserver(()=>{clearTimeout(rebuildTimeout);rebuildTimeout = setTimeout(()=>{requestAnimationFrame(rebuildSectionCache);},200);});if(DOM.sections){DOM.sections.forEach(section =>{resizeObserver.observe(section);});}});const initAudio =()=>{const audioBtn = document.getElementById('audio-toggle');const audio = document.getElementById('temple-audio');if(!audioBtn || !audio)return;let isPlaying = false;audio.volume = 0.4;audioBtn.addEventListener('click',()=>{if(isPlaying){audio.pause();audioBtn.classList.remove('playing');audioBtn.setAttribute('data-state','paused');audioBtn.setAttribute('aria-label','Play Temple Ambience');}else{audio.play().catch(err => console.log("Audio play failed:",err));audioBtn.classList.add('playing');audioBtn.setAttribute('data-state','playing');audioBtn.setAttribute('aria-label','Stop Temple Ambience');}isPlaying = !isPlaying;});};const initParallax =()=>{console.log('Parallax effect disabled(was causing CLS)');};const createMobileMenu =()=>{const toggle = document.querySelector('.nav-toggle');const menu = document.querySelector('.nav-menu');if(!toggle || !menu)return;toggle.addEventListener('click',()=>{const isOpen = menu.classList.toggle('open');toggle.setAttribute('aria-expanded',String(isOpen));});menu.querySelectorAll('a').forEach(link =>{link.addEventListener('click',()=>{menu.classList.remove('open');toggle.setAttribute('aria-expanded','false');});});document.addEventListener('click',(e)=>{if(!toggle.closest('header').contains(e.target)){menu.classList.remove('open');toggle.setAttribute('aria-expanded','false');}});};document.querySelectorAll('.btn').forEach(button =>{button.addEventListener('click',(e)=>{const bookTitle = e.target.closest('.book-card')?.querySelector('.book-title')?.textContent;const linkType = e.target.classList.contains('btn-primary')? 'PDF Download' : 'External Link';console.log(`User clicked: ${linkType}for ${bookTitle}`);});});document.querySelectorAll('a[target="_blank"]').forEach(link =>{link.addEventListener('click',function(){this.style.opacity = '0.6';setTimeout(()=>{this.style.opacity = '1';},300);});});const initParticles =()=>{const container = document.querySelector('.particles-container');if(!container)return;const particleCount = 15;for(let i = 0;i < particleCount;i++){const particle = document.createElement('div');particle.className = 'particle';particle.style.left = Math.random()* 100 + '%';particle.style.top = Math.random()* 100 + '%';particle.style.animationDelay =(i * 0.5)+ 's';particle.style.animationDuration =(6 + Math.random()* 4)+ 's';container.appendChild(particle);}};const initFAQ =()=>{const faqBlocks = document.querySelectorAll('.faq-block');faqBlocks.forEach(block =>{const summary = block.querySelector('summary');const content = block.querySelector('.faq-content');if(!summary || !content)return;if(!content.querySelector('.faq-content-inner')){const inner = document.createElement('div');inner.className = 'faq-content-inner';while(content.firstChild){inner.appendChild(content.firstChild);}content.appendChild(inner);}summary.addEventListener('click',(e)=>{e.preventDefault();const isOpen = block.hasAttribute('open');if(isOpen){const contentHeight = content.scrollHeight;requestAnimationFrame(()=>{content.style.maxHeight = contentHeight + 'px';requestAnimationFrame(()=>{content.style.maxHeight = '0';});});setTimeout(()=>{block.removeAttribute('open');content.style.maxHeight = '';},400);}else{const openBlocks = Array.from(document.querySelectorAll('.faq-block[open]')).filter(b => b !== block);const openData = openBlocks.map(openBlock =>{const openContent = openBlock.querySelector('.faq-content');return{block: openBlock,content: openContent,height: openContent.scrollHeight};});openData.forEach(data =>{requestAnimationFrame(()=>{data.content.style.maxHeight = data.height + 'px';requestAnimationFrame(()=>{data.content.style.maxHeight = '0';});});setTimeout(()=>{data.block.removeAttribute('open');data.content.style.maxHeight = '';},400);});block.setAttribute('open','');requestAnimationFrame(()=>{const contentHeight = content.scrollHeight;content.style.maxHeight = '0';requestAnimationFrame(()=>{content.style.maxHeight = contentHeight + 'px';});});setTimeout(()=>{content.style.maxHeight = 'none';},400);}});});};
